// ================= Chama contributions tracker =================

// ---- state ----
var KEY = "chama.payments";
var payments = loadPayments();
var nextId = payments.reduce((max, p) => Math.max(max, p.id), 0) + 1;

// ---- logic (pure) ----
function validatePayment(member, amount) {
  const errors = {};
  if (String(member).trim() === "") errors.member = "Enter a member name";
  const text = String(amount).trim();
  const n = Number(text);
  if (text === "") errors.amount = "Enter an amount";
  else if (!Number.isInteger(n) || n <= 0) errors.amount = "Amount must be a whole number above 0";
  return errors;
}

function totalsByMember(list) {
  const totals = list.reduce((t, p) => {
    t[p.member] = (t[p.member] || 0) + p.amount;
    return t;
  }, {});
  return Object.entries(totals)
    .map(([member, total]) => ({ member, total }))
    .sort((a, b) => b.total - a.total || a.member.localeCompare(b.member));
}

function grandTotal(list) {
  return list.reduce((sum, p) => sum + p.amount, 0);
}

// ---- storage ----
function isPayment(p) {
  return p !== null && typeof p === "object" && Number.isInteger(p.id) && typeof p.member === "string" && Number.isFinite(p.amount) && p.amount > 0;
}

function loadPayments() {
  try {
    const data = JSON.parse(localStorage.getItem(KEY));
    return Array.isArray(data) ? data.filter(isPayment) : [];
  } catch (err) {
    return [];
  }
}

function savePayments() {
  localStorage.setItem(KEY, JSON.stringify(payments));
}

// ---- actions: change state, save, redraw ----
function addPayment(member, amount) {
  const errors = validatePayment(member, amount);
  if (Object.keys(errors).length > 0) return errors;
  payments.push({ id: nextId++, member: String(member).trim(), amount: Number(amount) });
  savePayments();
  render();
  return {};
}

function removePayment(id) {
  payments = payments.filter((p) => p.id !== id);
  savePayments();
  render();
}

// ---- view ----
function render() {
  const list = document.getElementById("payments");
  list.innerHTML = "";
  for (const p of payments) {
    const li = document.createElement("li");
    const span = document.createElement("span");
    span.textContent = `${p.member}: ${p.amount} KSh`;
    const btn = document.createElement("button");
    btn.textContent = "Remove";
    btn.addEventListener("click", () => removePayment(p.id));
    li.appendChild(span);
    li.appendChild(btn);
    list.appendChild(li);
  }

  const totals = document.getElementById("totals");
  totals.innerHTML = "";
  for (const t of totalsByMember(payments)) {
    const li = document.createElement("li");
    li.textContent = `${t.member}: ${t.total} KSh`;
    totals.appendChild(li);
  }

  document.getElementById("grand").textContent = `Total: ${grandTotal(payments)} KSh`;
}

function showErrors(errors) {
  for (const field of ["member", "amount"]) {
    const message = errors[field] || "";
    document.getElementById(field + "-error").textContent = message;
    document.getElementById(field).classList.toggle("invalid", message !== "");
  }
}

// ---- wiring ----
document.getElementById("pay-form").addEventListener("submit", (event) => {
  event.preventDefault();
  const memberBox = document.getElementById("member");
  const amountBox = document.getElementById("amount");
  const errors = addPayment(memberBox.value, amountBox.value);
  showErrors(errors);
  if (Object.keys(errors).length > 0) return;
  document.getElementById("status").textContent = `Saved ${Number(amountBox.value)} KSh from ${memberBox.value.trim()}`;
  memberBox.value = "";
  amountBox.value = "";
  memberBox.focus();
});

render();

