function paidBy(payments) {
  return payments.reduce((t, p) => {
    t[p.member] = (t[p.member] || 0) + p.amount;
    return t;
  }, {});
}

function whoOwes(payments, members, target) {
  const paid = paidBy(payments);
  return members
    .map((m) => ({ member: m, owes: target - (paid[m] || 0) }))
    .filter((r) => r.owes > 0)
    .sort((a, b) => b.owes - a.owes || a.member.localeCompare(b.member));
}

function percentCollected(payments, members, target) {
  if (members.length === 0 || target <= 0) return 0;
  const paid = paidBy(payments);
  // each member counts at most the target, so one overpayment can't hide another's debt
  const counted = members.reduce((sum, m) => sum + Math.min(paid[m] || 0, target), 0);
  return Math.round((counted / (members.length * target)) * 1000) / 10;
}
